<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<link href="https://fonts.googleapis.com/css2?family=UnifrakturMaguntia&family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Dancing+Script:wght@500;700&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html,body{background:transparent;font-family:'Cormorant Garamond',serif;font-size:15px}
:root{
  --bg:#140D07;--pan:#1F150C;--pan2:#2A1D11;--pan3:#332412;
  --acc:#7A1220;--acc-rgb:122,18,32;
  --gold:#B8862E;--goldd:rgba(184,134,46,.14);
  --ink:#E8D9B8;--ink2:#B8A585;--mu:#7A6448;
  --bd:rgba(184,134,46,.22);--bd2:rgba(255,255,255,.06);
}
#ink-overlay{position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;pointer-events:none;opacity:0}
#ink-overlay.on{opacity:1;pointer-events:all}
#ink-blot{width:14px;height:14px;border-radius:50%;background:radial-gradient(circle,#0a0605 0%,rgba(10,6,5,.98) 55%,rgba(10,6,5,0) 78%);transform:scale(0);transition:transform 1.1s cubic-bezier(.2,.8,.3,1)}
#ink-overlay.on #ink-blot{transform:scale(140)}
#ink-msg{position:absolute;font-family:'Dancing Script',cursive;font-size:26px;color:var(--gold);opacity:0;transition:opacity .5s ease .6s;text-shadow:0 0 16px rgba(184,134,46,.5)}
#ink-overlay.on #ink-msg{opacity:1}

#ledger{max-width:460px;margin:6px auto;background:var(--bg);border-radius:3px;overflow:hidden;border:1px solid var(--bd);box-shadow:0 14px 50px rgba(0,0,0,.8),0 0 0 1px rgba(0,0,0,.5);position:relative}
#ledger::before{content:'';position:absolute;inset:0;pointer-events:none;z-index:5;opacity:.05;background-image:repeating-radial-gradient(circle at 20% 30%,#000 0,transparent 2px),repeating-radial-gradient(circle at 80% 70%,#000 0,transparent 2px);background-size:38px 38px,52px 52px}

/* MASTHEAD */
#mast{position:relative;padding:22px 20px 16px;text-align:center;background:linear-gradient(180deg,var(--pan) 0%,var(--bg) 100%);border-bottom:1px solid var(--bd)}
.corner-flourish{position:absolute;width:26px;height:26px;color:var(--gold);opacity:.5;font-size:20px;line-height:1}
.cf-tl{top:8px;left:10px}
.cf-tr{top:8px;right:10px;transform:scaleX(-1)}
#seal{width:50px;height:50px;margin:0 auto 10px;border-radius:50%;background:radial-gradient(circle at 35% 30%,rgba(var(--acc-rgb),.9),rgba(var(--acc-rgb),.65) 60%,rgba(var(--acc-rgb),.85) 100%);border:2px solid var(--gold);display:flex;align-items:center;justify-content:center;box-shadow:0 3px 10px rgba(0,0,0,.5),inset 0 0 12px rgba(0,0,0,.35)}
#mast-title{font-family:'UnifrakturMaguntia',cursive;font-size:26px;color:var(--ink);letter-spacing:.5px;text-shadow:0 0 18px rgba(var(--acc-rgb),.35);line-height:1.2}
#mast-sub{font-size:12px;font-style:italic;color:var(--ink2);margin-top:5px}

/* NAV RIBBON */
#navrib{display:flex;justify-content:center;gap:4px;padding:8px 10px;background:var(--pan);border-bottom:1px solid var(--bd2);flex-wrap:wrap}
.nav-a{font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:var(--mu);cursor:pointer;padding:3px 4px;transition:color .2s;user-select:none}
.nav-a:hover{color:var(--ink2)}
.nav-a.on{color:var(--gold)}
.nav-sep{color:var(--bd);font-size:9px;align-self:center}

/* PAGE BODY */
#page{padding:6px 20px 0;max-height:520px;overflow-y:auto}
#page::-webkit-scrollbar{width:4px}
#page::-webkit-scrollbar-thumb{background:var(--bd);border-radius:2px}

.leaf{padding:18px 0 6px;border-bottom:1px dashed var(--bd2)}
.leaf:last-of-type{border-bottom:none}
.leaf-hd{display:flex;align-items:center;gap:9px;margin-bottom:14px}
.leaf-hd .lh-num{font-family:'UnifrakturMaguntia',cursive;font-size:19px;color:var(--gold)}
.leaf-hd .lh-txt{font-size:11px;letter-spacing:3px;text-transform:uppercase;color:var(--gold);font-weight:600}
.leaf-hd::after{content:'';flex:1;height:1px;background:linear-gradient(90deg,var(--goldd),transparent)}

/* LEDGER LINE FIELDS */
.lline{display:flex;align-items:flex-end;gap:8px;margin-bottom:15px}
.lline-lbl{font-size:10px;letter-spacing:1.2px;text-transform:uppercase;color:var(--mu);flex-shrink:0;padding-bottom:5px;white-space:nowrap}
.lline input[type=text],.lline select{flex:1;min-width:0;background:transparent;border:none;border-bottom:1px solid var(--bd2);border-radius:0;padding:3px 2px 5px;color:var(--ink);font-family:'Cormorant Garamond',serif;font-size:15px;outline:none;transition:border-color .2s}
.lline input[type=text]:focus,.lline select:focus{border-bottom-color:var(--gold)}
.lline.trio{gap:10px}
.lline.trio .seg{flex:1;display:flex;align-items:flex-end;gap:5px;min-width:0}
select{appearance:none;-webkit-appearance:none;cursor:pointer}
select option{background:var(--pan)}
.ruled{width:100%;background:transparent;border:none;border-radius:0;color:var(--ink);font-family:'Cormorant Garamond',serif;font-size:15px;line-height:24px;outline:none;resize:vertical;min-height:72px;padding:0;
  background-image:repeating-linear-gradient(transparent,transparent 23px,var(--bd2) 23px,var(--bd2) 24px);}
.opt-tag{font-size:9px;color:var(--mu);font-style:italic;margin-left:5px}

/* WAX STAMPS (species) */
#stamps{display:flex;gap:16px;justify-content:center;margin:6px 0 16px}
.stamp{width:64px;height:64px;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;position:relative;transition:transform .18s;border:2px solid var(--bd2);background:var(--pan2)}
.stamp:hover{transform:translateY(-2px)}
.stamp .st-ico{font-size:20px;margin-bottom:2px;filter:grayscale(1);opacity:.55;transition:all .25s}
.stamp .st-lbl{font-size:8.5px;letter-spacing:1px;text-transform:uppercase;color:var(--mu);transition:color .25s}
.stamp.on{border-color:var(--gold);background:radial-gradient(circle at 35% 30%,rgba(var(--acc-rgb),.55),rgba(var(--acc-rgb),.3));animation:stampPress .3s ease}
.stamp.on .st-ico{filter:none;opacity:1}
.stamp.on .st-lbl{color:var(--ink)}
@keyframes stampPress{0%{transform:scale(1)}40%{transform:scale(.85)}100%{transform:scale(1)}}

/* WAX BLOBS (color) */
#blobs{display:flex;gap:9px;flex-wrap:wrap;justify-content:center;margin-bottom:6px}
.blob{width:26px;height:24px;cursor:pointer;border:2px solid transparent;transition:all .15s;border-radius:52% 48% 55% 45%/55% 45% 55% 45%;flex-shrink:0}
.blob:hover{transform:scale(1.12)}
.blob.on{border-color:var(--ink);box-shadow:0 0 0 2px rgba(0,0,0,.4)}
#customColorInput{width:26px;height:24px;padding:0;border:2px dashed var(--bd2);border-radius:52% 48% 55% 45%/55% 45% 55% 45%;cursor:pointer;background:var(--pan2)}

/* PINNED NOTE (species record) */
.pinned{background:var(--pan2);border:1px solid var(--bd2);border-radius:2px;padding:13px 14px;margin:4px 4px 16px;transform:rotate(-.6deg);box-shadow:0 6px 16px rgba(0,0,0,.35);position:relative}
.pinned::before{content:'📌';position:absolute;top:-11px;left:50%;transform:translateX(-50%);font-size:15px;filter:drop-shadow(0 2px 3px rgba(0,0,0,.5))}
.pinned .pin-ttl{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--gold);margin-bottom:9px;text-align:center}

/* GAUGES (stats) */
#gauge-row{display:flex;justify-content:space-between;gap:6px;margin:8px 0 18px;flex-wrap:wrap}
.gauge-col{display:flex;flex-direction:column;align-items:center;width:52px}
.gauge-tier{font-size:8px;color:var(--mu);text-align:center;margin-bottom:6px;height:22px;line-height:1.3}
.tube{width:16px;height:110px;border-radius:8px;background:var(--pan3);border:1px solid var(--bd2);position:relative;overflow:hidden}
.tube-fill{position:absolute;bottom:0;left:0;width:100%;border-radius:8px;transition:height .3s,background .3s}
.tube-bulb{width:24px;height:24px;border-radius:50%;background:var(--pan3);border:1px solid var(--bd2);margin-top:-6px;position:relative;z-index:2}
.tube-bulb-fill{position:absolute;inset:2px;border-radius:50%;transition:background .3s}
.gauge-slider{position:absolute;width:130px;height:30px;top:40px;left:-57px;transform:rotate(-90deg);-webkit-appearance:none;background:transparent;opacity:0;cursor:pointer;margin:0}
.gauge-slider::-webkit-slider-thumb{-webkit-appearance:none;width:20px;height:20px}
.gauge-nm{font-size:9px;color:var(--ink2);text-align:center;margin-top:7px;line-height:1.25;height:24px}

/* TICKET STUB (acts) */
.stub{position:relative;background:var(--pan2);border:1px dashed var(--bd);border-radius:3px;padding:11px 13px 11px 20px;margin-bottom:10px}
.stub::before{content:'';position:absolute;left:0;top:0;bottom:0;width:9px;background-image:radial-gradient(circle,var(--bg) 2.5px,transparent 2.6px);background-size:9px 11px;background-position:0 0}
.stub input[type=text],.stub textarea{width:100%;background:transparent;border:none;border-bottom:1px solid var(--bd2);color:var(--ink);font-family:'Cormorant Garamond',serif;font-size:14px;outline:none;margin-bottom:6px;padding:2px 0}
.stub textarea{border-bottom:none;height:38px;resize:none;line-height:1.4}
.stub-rm{position:absolute;top:8px;right:9px;font-size:10px;color:var(--mu);cursor:pointer;letter-spacing:1px}
.stub-add{width:100%;padding:9px;border:1.5px dotted var(--bd);background:transparent;color:var(--mu);font-size:11px;letter-spacing:1px;text-transform:uppercase;cursor:pointer;border-radius:3px;transition:all .2s}
.stub-add:hover{color:var(--gold);border-color:var(--gold)}

/* TRAIT CARDS */
.arcana-row{display:flex;gap:4px;margin-bottom:12px;flex-wrap:wrap}
.arcana{font-size:9.5px;letter-spacing:.5px;color:var(--mu);cursor:pointer;padding:4px 8px;border:1px solid var(--bd2);border-radius:2px;transition:all .18s;user-select:none}
.arcana.on{color:var(--gold);border-color:var(--gold);background:var(--goldd)}
.trait-wall{display:grid;grid-template-columns:1fr 1fr;gap:7px}
.tcard{position:relative;height:58px;border:1px solid var(--bd2);border-radius:3px;background:var(--pan2);overflow:hidden;cursor:pointer;transition:border-color .2s}
.tcard.chosen{border-color:var(--gold)}
.tcard-face{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:5px 7px;text-align:center;font-size:11px;color:var(--ink2);transition:opacity .25s}
.tcard-desc{position:absolute;inset:0;padding:6px 8px;font-size:9px;line-height:1.35;color:var(--ink2);background:rgba(10,6,4,.94);opacity:0;transform:translateY(6px);transition:all .25s;display:flex;align-items:center}
.tcard:hover .tcard-desc{opacity:1;transform:translateY(0)}
.tcard:hover .tcard-face{opacity:0}
.tcard-seal{position:absolute;top:3px;right:3px;width:13px;height:13px;border-radius:50%;background:var(--acc);border:1px solid var(--gold);display:none;align-items:center;justify-content:center;font-size:7px;color:var(--gold)}
.tcard.chosen .tcard-seal{display:flex}

/* SCENARIO ROLL CALL */
.roll-row{display:flex;align-items:baseline;gap:6px;padding:8px 4px;border-bottom:1px solid var(--bd2);cursor:pointer;transition:background .15s}
.roll-row:hover{background:var(--pan2)}
.roll-row.on .roll-mark{opacity:1}
.roll-mark{width:12px;flex-shrink:0;color:var(--gold);opacity:0;font-size:11px}
.roll-ico{flex-shrink:0;font-size:13px}
.roll-ttl{font-size:13px;color:var(--ink);white-space:nowrap;flex-shrink:0}
.roll-dots{flex:1;border-bottom:1px dotted var(--bd);min-width:14px;transform:translateY(-4px)}
.roll-desc{font-size:10px;color:var(--mu);font-style:italic;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:150px}
#scenarioCustomWrap{display:none;margin-top:10px}
#scenarioCustomWrap.on{display:block}

/* PINNED SOUL NOTE */
.torn-note{background:var(--pan2);border:1px solid var(--bd2);margin:6px 8px 16px;padding:12px 14px;transform:rotate(.7deg);box-shadow:0 6px 14px rgba(0,0,0,.3);clip-path:polygon(0 2%,3% 0,97% 1%,100% 3%,99% 97%,96% 100%,2% 99%,1% 96%)}

/* SIGNATURE / SUBMIT */
#sig-block{padding:20px 20px 22px;text-align:center;border-top:1px solid var(--bd)}
#sig-name{font-family:'Dancing Script',cursive;font-size:26px;color:var(--ink);min-height:36px;border-bottom:1px solid var(--bd);padding-bottom:6px;margin-bottom:6px}
#sig-cap{font-size:9.5px;letter-spacing:1.5px;text-transform:uppercase;color:var(--mu);margin-bottom:16px}
#seal-btn{width:78px;height:78px;border-radius:50%;margin:0 auto;background:radial-gradient(circle at 35% 30%,rgba(var(--acc-rgb),.95),rgba(var(--acc-rgb),.7) 65%,rgba(var(--acc-rgb),.9));border:2.5px solid var(--gold);display:flex;align-items:center;justify-content:center;flex-direction:column;cursor:pointer;box-shadow:0 6px 18px rgba(var(--acc-rgb),.4);transition:transform .15s}
#seal-btn:hover{transform:scale(1.05)}
#seal-btn:active{transform:scale(.94)}
#seal-btn span{font-size:9px;letter-spacing:1px;color:var(--ink);text-transform:uppercase;line-height:1.3;text-align:center}
</style>
</head>
<body>
<div id="ink-overlay"><div id="ink-blot"></div><div id="ink-msg">The ink dries...</div></div>

<textarea id="mnraw" style="display:none;position:absolute;left:-9999px">$1</textarea>
<div id="ledger">
