      <div style="margin-bottom:14px"><span class="lline-lbl" style="display:block;margin-bottom:5px">Personality</span>
        <textarea class="ruled" id="f-personality" placeholder="How do they think, feel, react?"></textarea>
      </div>
      <div class="lline"><span class="lline-lbl">Desire</span><input type="text" id="f-goal" placeholder="What do they truly seek?"></div>
      <div class="lline"><span class="lline-lbl">Bond</span><input type="text" id="f-bond" placeholder="Who matters most?"></div>
      <div class="lline"><span class="lline-lbl">Fear</span><input type="text" id="f-fear" placeholder="What haunts them?"></div>
