</div>

<script>
(function(){
function g(id){return document.getElementById(id)}
function gv(id){var e=g(id);return e?e.value.trim():''}
function esc(v){if(v==null)return'';return String(v)}

var curSpecies='human';
var currentColor='#7A1220';
var selTraits=[];
var acts=[];
var curScenario='';
var statVals={};
var initData=null;

var STATS=[
  {id:'cunning',nm:'Cunning'},
  {id:'agility',nm:'Agility & Grace'},
  {id:'willpower',nm:'Willpower'},
  {id:'mysticism',nm:'Mysticism'},
  {id:'charisma',nm:'Stage Presence'},
  {id:'force',nm:'Physical Force'}
];

var TRAIT_CATS=[
  {id:'stage',label:'I. Stage & Craft',traits:[
    {n:'Natural Showman',d:'Commands a room the moment they step into the light.'},
    {n:'Master of Illusion',d:'Deception is an art form, hard to tell from the truth.'},
    {n:'Silver-Tongued',d:'Words come easy, and are rarely entirely honest.'},
    {n:'Steady Hands',d:'Never trembles under pressure, on stage or off it.'},
    {n:'Perfectionist',d:'Every act is rehearsed until flawless, and never feels finished.'},
    {n:'Reckless Performer',d:'Takes the trick one step further than is safe, every time.'},
    {n:'Crowd-Pleaser',d:'Reads what an audience wants before they know it themselves.'},
    {n:'Backstage Whisperer',d:'Knows every secret the troupe keeps behind the curtain.'},
    {n:'Quick-Change Artist',d:'Vanishes and reappears as someone else before anyone blinks.'},
    {n:'Disciplined',d:'Years of practice have carved precision into every motion.'}
  ]},
  {id:'uncanny',label:'II. The Uncanny',traits:[
    {n:'Third Eye Sensitivity',d:'Perceives more of the spirit world than most, awakened or not.'},
    {n:'Ward-Marked',d:"Carries a symbol etched somewhere on the body, for protection."},
    {n:'Symbol-Touched',d:"Magic responds to them in ways it shouldn't, by any official account."},
    {n:'Spirit-Sighted',d:"Sees things at the edge of vision others insist aren't there."},
    {n:'Omen-Reader',d:'Finds meaning, real or imagined, in coincidence and portent.'},
    {n:'Skeptic of Magic',d:'Refuses to believe, even standing in front of the impossible.'},
    {n:'Haunted Dreams',d:'Sleep brings visions that linger long after waking.'},
    {n:'Ink-Stained Hands',d:'Marked, quite literally, by a life close to symbol-craft.'}
  ]},
  {id:'heart',label:'III. Heart',traits:[
    {n:'Loyal to the Troupe',d:'Family is chosen, and this one was chosen for keeps.'},
    {n:'Protective',d:'Steps between danger and loved ones without a second thought.'},
    {n:'Warm-Hearted',d:'Kindness that survives even a hard life on the road.'},
    {n:'Compassionate',d:"Feels the weight of others' pain as if it were their own."},
    {n:'Hopeful',d:'Believes, against the evidence, that things can get better.'},
    {n:'Devoted',d:'Gives everything to the people and causes that matter to them.'},
    {n:'Gentle Soul',d:"A softness the carnival life hasn't managed to burn away."},
    {n:'Fiercely Honest',d:'Cannot lie convincingly, even when it would be safer to.'},
    {n:'Found-Family Believer',d:'Blood means less than bonds forged under the big top.'},
    {n:'Forgiving',d:"Holds grudges loosely, even against those who've earned them."}
  ]},
  {id:'shadow',label:'IV. Shadow',traits:[
    {n:'Secretive',d:"Guards their past like it's the only thing they own."},
    {n:'Ruthless Bargainer',d:'Every deal favors them, and they make sure of it.'},
    {n:'Vengeful',d:"Old wounds don't close, they wait for the right moment."},
    {n:'Paranoid',d:'Trusts no one further than they can see them.'},
    {n:'Cold-Blooded',d:'Sentiment rarely factors into the decisions that matter.'},
    {n:'Manipulative',d:"People are pieces on a board, useful until they aren't."},
    {n:'Haunted by the Past',d:"Something follows them from town to town, and it isn't human."},
    {n:'Self-Destructive',d:'Courts ruin as if daring the world to stop them.'},
    {n:'Distrustful',d:'Kindness is assumed to have a price, always.'},
    {n:'Melancholic',d:'A quiet sadness colors even the brightest nights under the tent.'}
  ]}
];
var curTctCat='stage';

var SCENARIOS=[
  {id:'ordinary',ico:'🕯️',ttl:'Ordinary Life',desc:'Before the circus ever came to town.'},
  {id:'opening',ico:'🎪',ttl:'Opening Night',desc:'Nothing has been the same since.'},
  {id:'bargain',ico:'🖤',ttl:'The Bargain',desc:'A deal you cannot take back.'},
  {id:'onrun',ico:'🌘',ttl:'On the Run',desc:'Fleeing Kalgratti authorities.'},
  {id:'backstage',ico:'🎭',ttl:'Behind the Curtain',desc:'Among the troupe, between shows.'},
  {id:'aspett',ico:'🔬',ttl:'The Research Center',desc:"Inside Aspett's walls."},
  {id:'custom',ico:'✏️',ttl:'Custom',desc:'Define your own opening.'}
];

function hexRgb(h){return parseInt(h.slice(1,3),16)+','+parseInt(h.slice(3,5),16)+','+parseInt(h.slice(5,7),16)}
function setAccent(hex){
  currentColor=hex;
  var r=document.documentElement;
  r.style.setProperty('--acc',hex);
  r.style.setProperty('--acc-rgb',hexRgb(hex));
}

function statLevel(v){
  if(v<100)return{en:'Sideshow',color:'#7A6448'};
  if(v<300)return{en:'Understudy',color:'#9A8060'};
  if(v<500)return{en:'Featured Act',color:'#B09040'};
  if(v<700)return{en:'Headliner',color:'#B8862E'};
  if(v<850)return{en:'Star of the Show',color:'#A24868'};
  if(v<980)return{en:'Legend',color:'#5A3E8A'};
  if(v<1000)return{en:'Otherworldly',color:'#7A1220'};
  return{en:'Beyond the Veil',color:'#FFD700'};
}

function renderGauges(){
  var wrap=g('gauge-row');if(!wrap)return;
  var h='';
  STATS.forEach(function(s){
    var v=statVals[s.id]!=null?statVals[s.id]:200;
    statVals[s.id]=v;
    var lv=statLevel(v);
    var pct=v/10;
    h+='<div class="gauge-col">'+
      '<div class="gauge-tier" id="gtier-'+s.id+'" style="color:'+lv.color+'">'+lv.en+'</div>'+
      '<div class="tube" style="position:relative">'+
        '<div class="tube-fill" id="tfill-'+s.id+'" style="height:'+pct+'%;background:linear-gradient(180deg,'+lv.color+',rgba('+hexRgb(lv.color)+',.5))"></div>'+
        '<input type="range" class="gauge-slider" min="0" max="1000" value="'+v+'" id="stat-'+s.id+'">'+
      '</div>'+
      '<div class="tube-bulb"><div class="tube-bulb-fill" id="tbulb-'+s.id+'" style="background:'+lv.color+'"></div></div>'+
      '<div class="gauge-nm">'+s.nm+'</div>'+
    '</div>';
  });
  wrap.innerHTML=h;
  STATS.forEach(function(s){
    var inp=g('stat-'+s.id);
    if(inp)inp.addEventListener('input',function(){updateStat(s.id,parseInt(this.value))});
  });
}
function updateStat(id,v){
  statVals[id]=v;
  var lv=statLevel(v);
  var t=g('gtier-'+id);if(t){t.textContent=lv.en;t.style.color=lv.color}
  var f=g('tfill-'+id);if(f){f.style.height=(v/10)+'%';f.style.background='linear-gradient(180deg,'+lv.color+',rgba('+hexRgb(lv.color)+',.5))'}
  var b=g('tbulb-'+id);if(b)b.style.background=lv.color;
}

function renderArcana(){
  var row=g('arcana-row');if(!row)return;
  row.innerHTML=TRAIT_CATS.map(function(c){
    return '<div class="arcana'+(c.id===curTctCat?' on':'')+'" data-cat="'+c.id+'">'+c.label+'</div>';
  }).join('');
  renderTraitWall();
}
function renderTraitWall(){
  var wall=g('trait-wall');if(!wall)return;
  var cat=TRAIT_CATS.find(function(c){return c.id===curTctCat});
  if(!cat)return;
  wall.innerHTML=cat.traits.map(function(t){
    var on=selTraits.indexOf(t.n)>=0;
    return '<div class="tcard'+(on?' chosen':'')+'" data-n="'+esc(t.n)+'">'+
      '<div class="tcard-face">'+t.n+'</div>'+
      '<div class="tcard-desc">'+t.d+'</div>'+
      '<div class="tcard-seal">✦</div>'+
    '</div>';
  }).join('');
}

function renderActs(){
  var list=g('acts-list');if(!list)return;
  list.innerHTML=acts.map(function(a,i){
    return '<div class="stub" data-i="'+i+'">'+
      '<div class="stub-rm" data-rm="'+i+'">remove ×</div>'+
      '<input type="text" placeholder="Act name" value="'+esc(a.name||'').replace(/"/g,'&quot;')+'" data-f="name" data-i="'+i+'">'+
      '<textarea placeholder="What happens when they perform it..." data-f="desc" data-i="'+i+'">'+esc(a.desc||'')+'</textarea>'+
    '</div>';
  }).join('');
}
function saveActFields(){
  document.querySelectorAll('.stub input[data-f],.stub textarea[data-f]').forEach(function(el){
    var i=parseInt(el.getAttribute('data-i'));var f=el.getAttribute('data-f');
    if(acts[i])acts[i][f]=el.value;
  });
}

function renderRollCall(){
  var wrap=g('roll-call');if(!wrap)return;
  wrap.innerHTML=SCENARIOS.map(function(s){
    return '<div class="roll-row'+(curScenario===s.id?' on':'')+'" data-s="'+s.id+'">'+
      '<span class="roll-mark">✦</span><span class="roll-ico">'+s.ico+'</span>'+
      '<span class="roll-ttl">'+s.ttl+'</span><span class="roll-dots"></span>'+
      '<span class="roll-desc">'+s.desc+'</span>'+
    '</div>';
  }).join('');
}

document.querySelectorAll('.nav-a').forEach(function(a){
  a.addEventListener('click',function(){
    var target=g(this.getAttribute('data-jump'));
    if(target)target.scrollIntoView({behavior:'smooth',block:'start'});
  });
});
var page=g('page');
var leaves=document.querySelectorAll('.leaf');
if(page)page.addEventListener('scroll',function(){
  var best=null,bestDist=1e9;
  leaves.forEach(function(l){
    var d=Math.abs(l.getBoundingClientRect().top-page.getBoundingClientRect().top-4);
    if(d<bestDist){bestDist=d;best=l}
  });
  if(best){
    document.querySelectorAll('.nav-a').forEach(function(a){a.classList.toggle('on',a.getAttribute('data-jump')===best.id)});
  }
});

document.querySelectorAll('.stamp').forEach(function(st){
  st.addEventListener('click',function(){
    curSpecies=this.dataset.s;
    document.querySelectorAll('.stamp').forEach(function(x){x.classList.toggle('on',x===st)});
    document.querySelectorAll('.sp-sec').forEach(function(x){x.classList.toggle('on',x.dataset.sp===curSpecies)});
  });
});

document.querySelectorAll('.blob').forEach(function(b){
  b.addEventListener('click',function(){
    setAccent(this.dataset.c);
    document.querySelectorAll('.blob').forEach(function(x){x.classList.remove('on')});
    b.classList.add('on');
  });
});
g('customColorInput').addEventListener('input',function(){
  setAccent(this.value);
  document.querySelectorAll('.blob').forEach(function(x){x.classList.remove('on')});
});

g('f-nation').addEventListener('change',function(){
  g('nationCustomWrap').style.display=(this.value==='Custom')?'flex':'none';
});
g('f-role').addEventListener('change',function(){
  g('performerWrap').style.display=(this.value==='Circus Performer')?'flex':'none';
});

g('arcana-row').addEventListener('click',function(e){
  var a=e.target.closest('.arcana');if(!a)return;
  curTctCat=a.getAttribute('data-cat');
  renderArcana();
});
g('trait-wall').addEventListener('click',function(e){
  var card=e.target.closest('.tcard');if(!card)return;
  var n=card.getAttribute('data-n');
  var idx=selTraits.indexOf(n);
  if(idx>=0)selTraits.splice(idx,1);else selTraits.push(n);
  renderTraitWall();
});

g('act-add-btn').addEventListener('click',function(){
  saveActFields();
  acts.push({name:'',desc:''});
  renderActs();
});
g('acts-list').addEventListener('click',function(e){
  var rm=e.target.closest('.stub-rm');if(!rm)return;
  saveActFields();
  acts.splice(parseInt(rm.getAttribute('data-rm')),1);
  renderActs();
});

g('roll-call').addEventListener('click',function(e){
  var row=e.target.closest('.roll-row');if(!row)return;
  curScenario=row.getAttribute('data-s');
  renderRollCall();
  g('scenarioCustomWrap').classList.toggle('on',curScenario==='custom');
});

g('f-name').addEventListener('input',function(){
  var s=g('sig-name');
  s.textContent=this.value.trim()||' ';
});

/* Init from $1 */
var rawEl=g('mnraw');
if(rawEl&&rawEl.value.trim()){
  var dec=document.createElement('textarea');dec.innerHTML=rawEl.value.trim();
  try{initData=JSON.parse(dec.value.trim())}catch(e){}
}
curSpecies=(initData&&initData.species)||'human';
currentColor=(initData&&initData.charColor)||'#7A1220';
selTraits=(initData&&initData.traits)?initData.traits.slice():[];
acts=(initData&&initData.acts)?JSON.parse(JSON.stringify(initData.acts)):[];
curScenario=(initData&&initData.scenario)||'';
if(initData&&initData.stats)statVals=JSON.parse(JSON.stringify(initData.stats));

renderGauges();
renderArcana();
renderActs();
renderRollCall();
setAccent(currentColor);
document.querySelectorAll('.blob').forEach(function(b){b.classList.toggle('on',b.dataset.c===currentColor)});
document.querySelectorAll('.stamp').forEach(function(s){s.classList.toggle('on',s.dataset.s===curSpecies)});
document.querySelectorAll('.sp-sec').forEach(function(x){x.classList.toggle('on',x.dataset.sp===curSpecies)});
g('scenarioCustomWrap').classList.toggle('on',curScenario==='custom');

function sv(id,val){var e=g(id);if(e&&val!=null)e.value=val}
if(initData){
  sv('f-name',initData.name);sv('f-alias',initData.alias);sv('f-age',initData.age);
  sv('f-gender',initData.gender);sv('f-height',initData.height);sv('f-voice',initData.voice);
  sv('f-appearance',initData.appearance);sv('f-nation',initData.nation);sv('f-nationCustom',initData.nationCustom);
  sv('f-region',initData.region);sv('f-family',initData.family);sv('f-background',initData.background);
  sv('f-occupation',initData.occupation);sv('f-ahkonStance',initData.ahkonStance);sv('f-govTies',initData.govTies);
  sv('f-thirdEye',initData.thirdEye);sv('f-govStatus',initData.govStatus);
  sv('f-magicSpecialty',initData.magicSpecialty);sv('f-aspettHistory',initData.aspettHistory);
  sv('f-role',initData.role);sv('f-performerSpecialty',initData.performerSpecialty);
  sv('f-personality',initData.personality);sv('f-goal',initData.goal);sv('f-bond',initData.bond);
  sv('f-fear',initData.fear);sv('f-philosophy',initData.philosophy);sv('f-secret',initData.secret);
  sv('f-quote',initData.quote);sv('f-scenarioCustom',initData.scenarioCustom);
  if(initData.nation==='Custom')g('nationCustomWrap').style.display='flex';
  if(initData.role==='Circus Performer')g('performerWrap').style.display='flex';
  if(initData.name)g('sig-name').textContent=initData.name;
}

/* Auto-send to SillyTavern */
function sendToST(json){
  var oT='<'+'MARIONETTA_CONFIRM'+'>';var cT='<'+'/MARIONETTA_CONFIRM'+'>';
  var txt=oT+'\\n'+json+'\\n'+cT;
  try{
    var w=window.parent||window;
    var ta=w.document.getElementById('send_textarea')||
           w.document.querySelector('textarea.chat-input,#textareaAutosize,textarea');
    if(ta){
      var dd=Object.getOwnPropertyDescriptor(w.HTMLTextAreaElement.prototype,'value');
      if(dd&&dd.set)dd.set.call(ta,txt);else ta.value=txt;
      ta.dispatchEvent(new Event('input',{bubbles:true}));
      setTimeout(function(){
        try{
          var sb=w.document.getElementById('send_but');
          if(sb)sb.click();
          else ta.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));
        }catch(e2){}
      },150);
      return;
    }
  }catch(e){}
  try{navigator.clipboard.writeText(txt);}catch(e2){}
}

g('seal-btn').addEventListener('click',function(){
  saveActFields();
  var out={
    name:gv('f-name'),alias:gv('f-alias'),age:gv('f-age'),gender:gv('f-gender'),height:gv('f-height'),
    species:curSpecies,charColor:currentColor,voice:gv('f-voice'),appearance:gv('f-appearance'),
    nation:gv('f-nation')==='Custom'?gv('f-nationCustom'):gv('f-nation'),
    nationCustom:gv('f-nationCustom'),region:gv('f-region'),family:gv('f-family'),background:gv('f-background'),
    role:gv('f-role'),stats:{}
  };
  STATS.forEach(function(s){out.stats[s.id]=statVals[s.id]});
  if(curSpecies==='human'){
    out.occupation=gv('f-occupation');out.ahkonStance=gv('f-ahkonStance');out.govTies=gv('f-govTies');
  }else{
    out.thirdEye=gv('f-thirdEye');out.govStatus=gv('f-govStatus');
    out.magicSpecialty=gv('f-magicSpecialty');out.aspettHistory=gv('f-aspettHistory');
  }
  if(out.role==='Circus Performer')out.performerSpecialty=gv('f-performerSpecialty');
  out.traits=selTraits.slice();
  out.acts=acts.filter(function(a){return a.name||a.desc});
  out.personality=gv('f-personality');out.goal=gv('f-goal');out.bond=gv('f-bond');
  out.fear=gv('f-fear');out.philosophy=gv('f-philosophy');out.secret=gv('f-secret');out.quote=gv('f-quote');
  out.scenario=curScenario;out.scenarioCustom=gv('f-scenarioCustom');
  var json=JSON.stringify(out,null,2);
  var ov=g('ink-overlay');
  if(ov)ov.classList.add('on');
  setTimeout(function(){
    if(ov)ov.classList.remove('on');
    sendToST(json);
  },1700);
});
})();
</script>
</body>
</html>

