<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html,body{background:transparent;font-family:'Cormorant Garamond',serif;font-size:15px}
:root{
  --bg:#140D07;--pan:#1F150C;--pan2:#2A1D11;
  --acc:#7A1220;--acc-rgb:122,18,32;
  --gold:#B8862E;--goldd:rgba(184,134,46,.14);
  --ink:#E8D9B8;--ink2:#B8A585;--mu:#7A6448;
  --bd:rgba(184,134,46,.28);--bd2:rgba(255,255,255,.06);
}
#poster{max-width:460px;margin:6px auto;background:radial-gradient(ellipse at 50% 0%,var(--pan) 0%,var(--bg) 70%);position:relative;border-radius:2px;box-shadow:0 16px 55px rgba(0,0,0,.82);animation:pin .35s ease both;overflow:hidden}
@keyframes pin{from{opacity:0;transform:translateY(-6px) scale(.99)}to{opacity:1;transform:none}}
#poster::before{content:'';position:absolute;inset:10px;border:1px solid var(--bd);pointer-events:none;z-index:3}
#poster::after{content:'';position:absolute;inset:14px;border:1px solid var(--bd2);pointer-events:none;z-index:3}
.rosette{position:absolute;width:20px;height:20px;color:var(--gold);font-size:15px;display:flex;align-items:center;justify-content:center;z-index:4;opacity:.75}
.r-tl{top:12px;left:12px}.r-tr{top:12px;right:12px}.r-bl{bottom:12px;left:12px}.r-br{bottom:12px;right:12px}

#pcontent{position:relative;z-index:2;padding:34px 28px 26px;text-align:center}

#masthead{font-size:10px;letter-spacing:4px;text-transform:uppercase;color:var(--gold);margin-bottom:12px}
#pname{font-family:'UnifrakturMaguntia',cursive;font-size:34px;line-height:1.15;color:var(--ink);text-shadow:0 0 22px rgba(var(--acc-rgb),.4);word-break:break-word}
#prole{font-size:13px;font-style:italic;color:var(--ink2);margin-top:6px}

#medallion{width:74px;height:74px;border-radius:50%;margin:18px auto 14px;border:2px solid var(--gold);background:radial-gradient(circle at 35% 30%,rgba(var(--acc-rgb),.55),rgba(var(--acc-rgb),.25) 70%);display:flex;align-items:center;justify-content:center;font-size:30px;box-shadow:0 4px 14px rgba(0,0,0,.4),inset 0 0 14px rgba(0,0,0,.3)}

