    <div id="pfoot">
      <span id="admit">✦ Admit One ✦</span>
      <div id="pfinegrid"></div>
    </div>
  </div>
</div>

<script>
(function(){
function g(id){return document.getElementById(id)}
function esc(v){if(v==null)return'';return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}

var STATS=[
  {id:'cunning',nm:'Cunning'},
  {id:'agility',nm:'Agility & Grace'},
  {id:'willpower',nm:'Willpower'},
  {id:'mysticism',nm:'Mysticism'},
  {id:'charisma',nm:'Stage Presence'},
  {id:'force',nm:'Physical Force'}
];

var SCENARIOS={
  ordinary:{ico:'🕯️',ttl:'Ordinary Life',desc:'Before the circus ever came to town.'},
  opening:{ico:'🎪',ttl:'Opening Night',desc:'Nothing has been the same since.'},
  bargain:{ico:'🖤',ttl:'The Bargain',desc:'A deal you cannot take back.'},
  onrun:{ico:'🌘',ttl:'On the Run',desc:'Fleeing Kalgratti authorities.'},
  backstage:{ico:'🎭',ttl:'Behind the Curtain',desc:'Among the troupe, between shows.'},
  aspett:{ico:'🔬',ttl:'The Research Center',desc:"Inside Aspett's walls."}
};

function statLevel(v){
  if(v<100)return{en:'Sideshow',color:'#7A6448'};
  if(v<300)return{en:'Understudy',color:'#9A8060'};
  if(v<500)return{en:'Featured Act',color:'#B09040'};
  if(v<700)return{en:'Headliner',color:'#B8862E'};
  if(v<850)return{en:'Star of the Show',color:'#A24868'};
  if(v<980)return{en:'Legend',color:'#5A3E8A'};
  if(v<1000)return{en:'Otherworldly',color:'#7A1220'};
  return{en:'Beyond the Veil',color:'#FFD700'};
}

var raw=g('mnraw');var d=null;
if(raw&&raw.value.trim()){
  var dec=document.createElement('textarea');dec.innerHTML=raw.value.trim();
  try{d=JSON.parse(dec.value.trim())}catch(e){}
}
if(!d)d={};

var acc=d.charColor||'#7A1220';
document.documentElement.style.setProperty('--acc',acc);
function hexRgb(h){return parseInt(h.slice(1,3),16)+','+parseInt(h.slice(3,5),16)+','+parseInt(h.slice(5,7),16)}
try{document.documentElement.style.setProperty('--acc-rgb',hexRgb(acc))}catch(e){}

var sp=d.species||'human';
g('pname').textContent=d.name||'Unnamed';
var roleLine=(sp==='ahkon'?"Ah'kon":'Human')+(d.role?' · '+d.role:'')+(d.alias?' · "'+d.alias+'"':'');
g('prole').textContent=roleLine;
g('medallion').textContent=(sp==='ahkon'?'👁':'🎭');

var traits=d.traits||[];
var tagEl=g('tagline');
if(traits.length){
  tagEl.innerHTML=traits.slice(0,4).map(function(t){return '<span class="tag-flag">'+esc(t)+'</span>';}).join('');
}else{
  tagEl.innerHTML='<span class="mc-empty">No traits recorded</span>';
}

/* BILLING */
var billEl=g('billing');
if(billEl){
  var bh='';
  STATS.forEach(function(s){
    var v=(d.stats&&d.stats[s.id]!=null)?d.stats[s.id]:0;
    var lv=statLevel(v);
    bh+='<div class="bill-row"><span class="bill-nm">'+s.nm+'</span><span class="bill-dots"></span><span class="bill-lvl" style="color:'+lv.color+'">'+lv.en+'</span></div>';
  });
  billEl.innerHTML=bh;
}

/* ENGAGEMENT */
var engEl=g('engagement');
if(engEl){
  var eh='';
  if(d.personality)eh+='<p><span class="lbl">Personality</span>'+esc(d.personality)+'</p>';
  if(d.background)eh+='<p><span class="lbl">Origin</span>'+esc(d.background)+'</p>';
  var extras=[];
  if(d.goal)extras.push('seeks '+d.goal.toLowerCase());
  if(d.bond)extras.push('bound to '+d.bond.toLowerCase());
  if(d.fear)extras.push('fears '+d.fear.toLowerCase());
  if(extras.length)eh+='<p><span class="lbl">Known For</span>'+esc(extras.join(' · '))+'</p>';
  if(!eh)eh='<div class="mc-empty">No dossier notes recorded.</div>';
  engEl.innerHTML=eh;
}

if(d.quote){
  var pq=g('pullquote');
  pq.style.display='block';
  pq.textContent='"'+d.quote+'"';
}

/* SECRET STUB */
if(d.secret){
  g('stub-wrap').style.display='block';
  g('stub-txt').textContent=d.secret;
  g('stub').addEventListener('click',function(){this.classList.toggle('revealed')});
}

/* PERFORMANCE */
var perfEl=g('perf');
if(perfEl){
  var sc=d.scenario;var info=SCENARIOS[sc];
  if(sc==='custom'){
    perfEl.innerHTML='<span id="perf-ico">✏️</span><div><div id="perf-ttl">Custom Opening</div><div id="perf-desc">'+esc(d.scenarioCustom||'')+'</div></div>';
  }else if(info){
    perfEl.innerHTML='<span id="perf-ico">'+info.ico+'</span><div><div id="perf-ttl">'+info.ttl+'</div><div id="perf-desc">'+info.desc+'</div></div>';
  }else{
    perfEl.innerHTML='<div class="mc-empty">No performance scheduled</div>';
  }
}

/* FINE PRINT FOOTER */
var fineRows=[];
if(d.nation)fineRows.push(d.nation);
if(d.region)fineRows.push(d.region);
if(sp==='ahkon'&&d.govStatus)fineRows.push(d.govStatus);
if(sp==='human'&&d.occupation)fineRows.push(d.occupation);
g('pfinegrid').textContent=fineRows.join('   ·   ');
})();
</script>
</body>
</html>

