function hexRgb(h){return parseInt(h.slice(1,3),16)+','+parseInt(h.slice(3,5),16)+','+parseInt(h.slice(5,7),16)}

var raw=g('wtraw');var d=null;
if(raw&&raw.value.trim()){
  var dec=document.createElement('textarea');dec.innerHTML=raw.value.trim();
  try{d=JSON.parse(dec.value.trim())}catch(e){}
}
if(!d)d={};

function tierColor(pct){
  if(pct<25)return 'var(--safe)';
  if(pct<50)return 'var(--caution)';
  if(pct<75)return 'var(--concern)';
  return 'var(--danger)';
}
function tierColorInv(pct){return tierColor(100-pct)}

/* WAYPOINT */
var loc=d.location||{};
g('loc-name').textContent=loc.name||'Unknown Waypoint';
g('loc-region').textContent=loc.region||'';
g('loc-desc').textContent=loc.description||'';
g('v-date').textContent=d.date||'—';
g('v-season').textContent=d.season||'—';
g('v-weather').textContent=d.weather||'—';

/* GAUGES */
var GAUGES=[
  {key:'warStatus',ico:'⚔️',lbl:'War Abroad',fn:tierColor},
  {key:'troupeWelcome',ico:'🎪',lbl:"Troupe's Welcome",fn:tierColorInv},
  {key:'ahkonWatch',ico:'👁️',lbl:"Ah'kon Watch",fn:tierColor}
];
var gRow=g('gauge-row');
if(gRow){
  var gh='';
  GAUGES.forEach(function(gg){
    var obj=d[gg.key]||{};
    var lvl=obj.level!=null?obj.level:0;
    var lbl=obj.label||'Unknown';
    var col=gg.fn(lvl);
    gh+='<div class="gcol">'+
      '<span class="gcol-ico">'+gg.ico+'</span>'+
      '<div class="gcol-lbl">'+gg.lbl+'</div>'+
      '<div class="tube"><div class="tube-fill" style="height:'+lvl+'%;background:'+col+'"></div></div>'+
      '<div class="tube-bulb"><div class="tube-bulb-fill" style="background:'+col+'"></div></div>'+
      '<div class="gcol-state" style="color:'+col+'">'+esc(lbl)+'</div>'+
      (obj.note?'<div class="gcol-note">'+esc(obj.note)+'</div>':'')+
    '</div>';
  });
  gRow.innerHTML=gh;
}

/* DANGER BADGE */
var dl=d.dangerLevel||{};
var dlVal=dl.level!=null?dl.level:0;
var dlCol=tierColor(dlVal);
var ring=g('db-ring');
if(ring){ring.style.borderColor=dlCol;ring.style.boxShadow='0 0 10px -2px '+dlCol;}
g('db-val').textContent=dlVal;
g('db-val').style.color=dlCol;

/* ASPETT SHADOW */
var shEl=g('shadow-content');
var sh=d.aspettShadow||{};
if(sh.active&&sh.scheme){
  shEl.innerHTML='<div class="shadow-box"><div class="shadow-ttl">Threat: '+esc(sh.threatLevel||'Unknown')+'</div>'+
    '<div class="shadow-txt">'+esc(sh.scheme)+'</div></div>';
}else{
  shEl.innerHTML='<div class="shadow-inactive">No known activity from Aspett at this time.</div>';
}

/* ROLL CALL */
var rcEl=g('rollcall-list');
var present=d.present||[];
if(present.length){
  rcEl.innerHTML=present.map(function(p){
    return '<div class="person-row"><div class="person-dot"></div><div>'+
      '<span class="person-nm">'+esc(p.name||'—')+'</span>'+
      (p.role?'<span class="person-role">'+esc(p.role)+'</span>':'')+
      (p.note?'<div class="person-note">'+esc(p.note)+'</div>':'')+
    '</div></div>';
  }).join('');
}else{
  rcEl.innerHTML='<div class="empty-note">No one of note nearby.</div>';
}

/* WHISPERS */
var wEl=g('whispers-list');
var rumors=d.rumors||[];
if(rumors.length){
  wEl.innerHTML=rumors.map(function(r,i){
    var rot=(i%2===0?-1:1)*(0.4+Math.random()*0.6);
    return '<div class="whisper" style="--rot:'+rot.toFixed(2)+'deg">'+
      (r.tag?'<div class="whisper-tag">'+esc(r.tag)+'</div>':'')+
      '<div class="whisper-txt">'+esc(r.text||'')+'</div>'+
    '</div>';
  }).join('');
}else{
  wEl.innerHTML='<div class="empty-note">The town keeps quiet, for now.</div>';
}

/* NAV + COLLAPSE */
document.querySelectorAll('.nav-a').forEach(function(a){
  a.addEventListener('click',function(e){
    e.stopPropagation();
    var target=g(this.getAttribute('data-jump'));
    if(target)target.scrollIntoView({behavior:'smooth',block:'start'});
  });
});
var page=g('page');
var leaves=document.querySelectorAll('.leaf');
if(page)page.addEventListener('scroll',function(){
  var best=null,bestDist=1e9;
  leaves.forEach(function(l){
    var dd=Math.abs(l.getBoundingClientRect().top-page.getBoundingClientRect().top-4);
    if(dd<bestDist){bestDist=dd;best=l}
  });
  if(best)document.querySelectorAll('.nav-a').forEach(function(a){a.classList.toggle('on',a.getAttribute('data-jump')===best.id)});
});

var mast=g('mast');
if(mast)mast.addEventListener('click',function(){g('wtwin').classList.toggle('closed')});
})();
</script>
</body>
</html>

